using Side = std::map<Price, Qty>;                  // price → total qty
struct OrderBook { Side bids, asks; };              // best bid = rbegin, best ask = begin
struct Level { Price price; Qty qty; };
std::unordered_map<std::string, OrderBook> books_;  // exchange → book

void build(const std::vector<Order>& orders) {
    for (const auto& [exch, price, qty, side] : orders) {
        OrderBook& book = books_[exch];
        (side == "bid" ? book.bids : book.asks)[price] += qty;   // same price: sum
    }
    nbbo_ = {national(true), national(false)};      // precompute → O(1) queries
}

// One pass: a better price resets the qty, a tie adds to it.
std::optional<Level> national(bool bid) const {
    std::optional<Level> best;
    for (const auto& [exch, book] : books_) {
        const Side& s = bid ? book.bids : book.asks;
        if (s.empty()) continue;
        auto [px, qty] = bid ? *s.rbegin() : *s.begin();     // this exchange's best
        if (!best || (bid ? px > best->price : px < best->price))
            best = Level{px, qty};                           // better: reset
        else if (px == best->price)
            best->qty += qty;                                // tie: add
    }
    return best;
}
